 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # A fully empty row is completed by copying the preceding row.
    for r, row in enumerate(out):
        if all(v == 0 for v in row) and r > 0:
            out[r] = out[r - 1][:]
    return out

